  "description": "Model Context Protocol server exposing GitLab REST + GraphQL operations as AI tools, ~875 on Free/CE and up to ~1102 on GitLab.com Ultimate: merge requests, pipelines, issues, releases, milestones, and more. One self-contained Go binary with no runtime to install; stdio or HTTP transport, with dynamic/meta/individual tool surfaces, plus resource subscriptions (live change notifications by polling).",
  "author": "José M. Requena Plens",
  "authorUrl": "https://github.com/jmrplens",
  "cloudEndpoint": "https://mcp.jmrp.io/gitlab",
  "icon": "https://raw.githubusercontent.com/jmrplens/gitlab-mcp-server/main/mcpb/icon.png",
  "tags": [
    "gitlab",
    "mcp",
    "devops",
    "ci-cd",
    "merge-requests",
    "issues",
    "pipelines",
    "git",
    "go",
    "graphql"
  ],
  "tools": [
    {
      "name": "gitlab_execute_action",
      "title": "GitLab Execute Action",
      "description": "Execute one GitLab catalog action by canonical ID or alias. Always pass params as an object. Destructive actions require top-level confirm=true. Use find first only when action or params are unclear. Example: {\"action\":\"issue.list\",\"params\":{\"project_id\":\"group/project\"}}",
      "inputSchema": {
        "additionalProperties": false,
        "properties": {
          "action": {
            "description": "Canonical action ID returned by gitlab_find_action, or a supported compatibility alias, such as project.list, issue.update, or issue.close.",
            "type": "string",
            "x-mcp-header": "Action"
          },
          "confirm": {
            "description": "Set top-level confirm=true to explicitly approve destructive actions. Do not put confirm inside params for gitlab_execute_action.",
            "type": "boolean"
          },
          "params": {
            "additionalProperties": true,
            "description": "Required action-specific parameters object validated by the selected action schema. Use an empty object for actions with no parameters.",
            "properties": {},
            "type": "object"
          }
        },
        "required": [
          "action",
          "params"
        ],
        "type": "object"
      },
      "annotations": {
        "destructiveHint": true,
        "idempotentHint": false,
        "openWorldHint": true,
        "readOnlyHint": false
      }
    },
    {
      "name": "gitlab_find_action",
      "title": "GitLab Find Action",
      "description": "Search the local GitLab action catalog. Read-only and no GitLab API call. Use when the action ID or params are unclear. Returns schemas, hints, destructive flags, and execute examples. Example: {\"query\":\"issue list\"}",
      "inputSchema": {
        "additionalProperties": false,
        "properties": {
          "explain": {
            "description": "When true, include deterministic scoring reasons for each returned action. Defaults to false to keep responses compact.",
            "type": "boolean"
          },
          "limit": {
            "description": "Maximum number of matches to return. Defaults to 20 and is capped at 50.",
            "type": "integer"
          },
          "query": {
            "description": "Search terms combining a GitLab domain or resource with a verb, filter, or object name, such as project create, merge request approve, pipeline retry, issue delete, or ci variable. At most 256 characters: a longer query is refused, not truncated.",
            "maxLength": 256,
            "type": "string"
          }
        },
        "required": [
          "query"
        ],
        "type": "object"
      },
      "annotations": {
        "destructiveHint": false,
        "idempotentHint": true,
        "openWorldHint": true,
        "readOnlyHint": true
      }
    }
  ],
