      "arguments": [
        {
          "name": "username",
          "title": "Username",
          "description": "GitLab username to report on",
          "required": true
        },
        {
          "name": "days",
          "title": "Days",
          "description": "Number of days to look back, a positive integer (default: 7)"
        }
      ]
    },
    {
      "name": "user_stats",
      "title": "User Stats",
      "description": "Generate statistics for a user: contribution events across all projects with their breakdown, daily activity trends and a Mermaid activity chart, and the project's merge request stats (authored/assigned/reviewed by state) and issue stats (authored/assigned by state), up to 100 per list. Use this for performance reviews, productivity tracking, or personal dashboards.",
      "arguments": [
        {
          "name": "project_id",
          "title": "Project ID",
          "description": "Project ID (numeric) or full path as written (e.g. 'group/project'), not URL-encoded",
          "required": true
        },
        {
          "name": "username",
          "title": "Username",
          "description": "GitLab username to generate stats for (defaults to the authenticated user if omitted)"
