{
  "$schema": "https://static.modelcontextprotocol.io/schemas/2025-12-11/server.schema.json",
  "name": "io.github.jmrplens/gitlab-mcp-server",
  "title": "GitLab MCP Server",
  "description": "Go MCP server for GitLab: 2 dynamic tools reach ~879 actions on Free/CE, up to ~1106 on Ultimate.",
  "version": "3.7.0",
  "repository": {
    "url": "https://github.com/jmrplens/gitlab-mcp-server",
    "source": "github",
    "id": "1208139072"
  },
  "websiteUrl": "https://docs.jmrp.io/gitlab-mcp-server/",
  "icons": [
    {
      "src": "https://raw.githubusercontent.com/jmrplens/gitlab-mcp-server/main/site/public/favicon.svg",
      "mimeType": "image/svg+xml",
      "sizes": [
        "any"
      ]
    },
    {
      "src": "https://raw.githubusercontent.com/jmrplens/gitlab-mcp-server/main/site/public/logo-400.png",
      "mimeType": "image/png",
      "sizes": [
        "400x400"
      ]
    }
  ],
  "packages": [
    {
      "registryType": "oci",
      "identifier": "ghcr.io/jmrplens/gitlab-mcp-server:3.7.0@sha256:061d97d0097b13d93fe97bb0aab2e0088910887fd0434765dbb3227a5e14bf9c",
      "transport": {
        "type": "stdio"
      },
      "environmentVariables": [
        {
          "name": "GITLAB_URL",
          "description": "GitLab instance URL (default: https://gitlab.com; set for self-managed instances)",
          "isRequired": false,
          "placeholder": "https://gitlab.com",
          "default": "https://gitlab.com"
        },
        {
          "name": "GITLAB_TOKEN",
          "description": "GitLab Personal Access Token (glpat-...)",
          "isRequired": true,
          "isSecret": true,
          "placeholder": "glpat-xxxxxxxxxxxxxxxxxxxx"
        },
        {
          "name": "GITLAB_MCP_SKIP_TLS_VERIFY",
          "description": "Skip TLS certificate verification for self-signed certs (default: false)",
          "isRequired": false,
          "default": "false",
          "format": "boolean"
        },
        {
          "name": "GITLAB_MCP_TOOL_SURFACE",
          "description": "Tool catalog selector: dynamic, meta, or individual (default: dynamic)",
          "isRequired": false,
          "default": "dynamic",
          "choices": [
            "meta",
            "individual",
            "dynamic"
          ]
        },
        {
          "name": "GITLAB_MCP_CAPABILITY_SURFACE",
          "description": "Resource and prompt catalog selector: full or minimal (default: full); resource subscriptions require full",
          "isRequired": false,
          "default": "full",
          "choices": [
            "full",
            "minimal"
          ]
        },
        {
          "name": "GITLAB_MCP_META_PARAM_SCHEMA",
          "description": "Meta-tool input schema detail: opaque, compact, or full (default: opaque)",
          "isRequired": false,
          "default": "opaque",
          "choices": [
            "opaque",
            "compact",
            "full"
          ]
        },
        {
          "name": "GITLAB_MCP_TIER",
          "description": "GitLab tier: free/ce, premium or ultimate, used as given. When unset, detected from the instance license, then from the plans of the namespaces the token administers, then, on GitLab.com, from the top-level groups the token is a member of, falling back to free. Gates Premium and Ultimate actions; GitLab.com Ultimate also serves the Orbit Knowledge Graph tools",
          "isRequired": false,
          "choices": [
            "free",
            "ce",
            "premium",
            "ultimate"
          ]
        },
        {
          "name": "GITLAB_MCP_READ_ONLY",
          "description": "Read-only mode: removes every mutating action from the served surface; reads keep working (default: false)",
          "isRequired": false,
          "default": "false",
          "format": "boolean"
        },
        {
          "name": "GITLAB_MCP_SAFE_MODE",
          "description": "Safe mode: a mutating action returns a preview card naming the action and echoing its arguments instead of running; reads keep working (default: false)",
          "isRequired": false,
          "default": "false",
          "format": "boolean"
        },
        {
          "name": "GITLAB_MCP_EMBEDDED_RESOURCES",
          "description": "Append EmbeddedResource content blocks (clickable links to MCP resources) to get_* tool results (default: true)",
          "isRequired": false,
          "default": "true",
          "format": "boolean"
        },
        {
          "name": "GITLAB_MCP_EXCLUDE_TOOLS",
          "description": "Comma-separated tool names, group names or canonical action IDs to exclude, on every surface (e.g. gitlab_admin,gitlab_runner)",
          "isRequired": false,
          "placeholder": "gitlab_admin,gitlab_runner"
        },
        {
          "name": "GITLAB_MCP_IGNORE_SCOPES",
          "description": "Skip the scope filter and the read_api narrowing and register all tools regardless of token permissions; a token carrying neither read_api nor api is still refused (default: false)",
          "isRequired": false,
          "default": "false",
          "format": "boolean"
        },
        {
          "name": "GITLAB_MCP_UPLOAD_MAX_FILE_SIZE",
          "description": "Largest local file an upload or file-reading action accepts, in bytes or with a KB, MB or GB suffix (e.g. 2GB); at most 1 TB (default: 2147483648, 2 GB)",
          "isRequired": false,
          "default": "2147483648"
        },
        {
          "name": "GITLAB_MCP_ALLOWED_UPLOAD_DIRS",
          "description": "Extra OS path-list-separated directories an action may read a local file from; the working directory (unless it is the filesystem root or your home directory) and the OS temp directory are always allowed. Unused in HTTP mode, which refuses local paths",
          "isRequired": false,
          "placeholder": "/path/to/files:/another/path/to/files"
        },
        {
          "name": "GITLAB_MCP_ALLOWED_DOWNLOAD_DIRS",
          "description": "Extra OS path-list-separated directories an action may write a downloaded file into; the working directory (unless it is the filesystem root or your home directory) and the OS temp directory are always allowed. Unused in HTTP mode, which refuses local paths",
          "isRequired": false,
          "placeholder": "/path/to/downloads:/another/path/to/downloads"
        },
        {
          "name": "GITLAB_MCP_ALLOWED_IMPORT_DIRS",
          "description": "Extra OS path-list-separated directories a project or group import archive may be read from; the working directory (unless it is the filesystem root or your home directory) and the OS temp directory are always allowed. Unused in HTTP mode, which refuses local paths",
          "isRequired": false,
          "placeholder": "/path/to/exports:/another/path/to/exports"
        },
        {
          "name": "GITLAB_MCP_RATE_LIMIT_RPS",
          "description": "Rate limit per credential, in requests per second, on every call that reaches GitLab, with tools/list charged to a bucket of its own; 0, the default on stdio, disables it (default: 0)",
          "isRequired": false,
          "default": "0",
          "format": "number"
        },
        {
          "name": "GITLAB_MCP_RATE_LIMIT_BURST",
          "description": "Token-bucket burst size when GITLAB_MCP_RATE_LIMIT_RPS is greater than 0 (default: 40)",
          "isRequired": false,
          "default": "40",
          "format": "number"
        },
        {
          "name": "GITLAB_MCP_LOG_LEVEL",
          "description": "Logging verbosity (default: info)",
          "isRequired": false,
          "default": "info",
          "choices": [
            "debug",
            "info",
            "warn",
            "error"
          ]
        },
        {
          "name": "GITLAB_MCP_LANGUAGE",
          "description": "Language of the elicitation questions, form field titles and progress messages a client shows the user: en or es (default: en). What the model reads stays English",
          "isRequired": false,
          "default": "en",
          "choices": [
            "en",
            "es"
          ]
        }
      ]
    },
